// ssba-18 — Aphex Twin, "18 SsbA" (dump do SoundCloud, user48736353001, 2015). bpm 112.
//
// Não é SAW vol.2. É o outro Richard: o das fitas de 91 que ele largou na
// internet em 2015 sem masterizar. Ambient techno com pulso — bumbo abafado,
// acorde longo, e uma melodia curta que só aparece depois de um minuto e meio.
//
// A diferença técnica pro `stone-em-foco` é uma só: ali a peça é um estado,
// aqui ela tem assunto. O assunto é a melodia do passo 5, e tudo antes dela é
// preparação. Por isso ela entra tarde e sai antes do fim: a única vez que uma
// melodia soa como acontecimento é quando o ouvido já desistiu de esperar.
//
// A gêmea desafinada (camada 7) é o truque do disco inteiro: a mesma linha,
// 12 cents acima, entrando um passo depois. Não é chorus de plugin — é o
// batimento entre duas vozes que nunca afinam, e é isso que soa "fita".
//
// ── ARRANJO ── cada casa = 8 ciclos (~17 s em 112 bpm), oito casas ≈ 2min20
//              1    2    3    4    5    6    7    8
//   placa      ●    ●    ●    ●    ●    ●    ●    ●    a cama, nunca sai
//   acordes    ·    ●    ●    ●    ●    ·    ●    ●    cala no auge da melodia
//   sub        ·    ·    ●    ●    ●    ●    ●    ·
//   bumbo      ·    ·    ·    ●    ●    ●    ●    ·    o pulso entra no 4
//   chocalho   ·    ·    ·    ·    ●    ●    ·    ·    só no auge
//   melodia    ·    ·    ·    ·    ●    ●    ●    ·    o assunto
//   gêmea      ·    ·    ·    ·    ·    ●    ●    ·    a mesma, 12 cents acima
//   fita       ●    ●    ●    ●    ●    ●    ●    ●
//
// Passo 6 é o nó: os acordes SAEM e a gêmea entra. Tira-se o chão harmônico
// justo quando a melodia dobra — ela fica exposta, e o ouvido é obrigado a
// escutar a desafinação em vez do acorde.
stack(
  // 1. a placa: pad escuro do Dream Zone (n27, zcr 179 — o mais surdo do banco),
  //    rodando em 8 compassos com a rotação da fita oscilando meio por cento
  s("zero_g_ce07_dream_zone").n(27)
    .struct("x").slow(8)
    .begin(0.05).end(0.62)
    .speed(sine.slow(13).range(0.995, 1.005))
    .gain(0.3).lpf(sine.slow(23).range(700, 2200))
    .room(0.78).size(7).pan(0.45),

  // 2. os acordes: C#m – A – F#m – B, um por compasso. Serra com filtro fechado
  //    e ataque de 900 ms — a nota chega depois do tempo, de propósito.
  note("<[c#3,e3,g#3] [a2,c#3,e3] [f#2,a2,c#3] [b2,d#3,f#3]>").s("sawtooth")
    .struct("x")
    .attack(0.9).release(1.6).sustain(0.75)
    .gain(0.15).lpf(sine.slow(17).range(550, 1400))
    .room(0.7).size(6).pan(0.55)
    .mask("<0 1 1 1 1 0 1 1>/8"),

  // 3. o sub: a fundamental, sem ataque. Sozinho ele é inaudível em laptop —
  //    está aqui pro sistema grande, não pra mixagem de fone.
  note("<c#2 a1 f#1 b1>").s("sine")
    .struct("x")
    .attack(0.6).release(2).gain(0.34).lpf(160)
    .mask("<0 0 1 1 1 1 1 0>/8"),

  // 4. o bumbo: KICK - PUTARIA (n6, 0,77 s — o mais longo do kit), com o filtro
  //    em 110 Hz. Não é batida de pista: é pulso, quase só o corpo.
  s("vhulto_sampling_the_world_drumkit_kick").n(6)
    .struct("x ~ ~ ~ x ~ ~ ~")
    .gain(0.6).lpf(110).shape(0.15)
    .room(0.2).size(3)
    .mask("<0 0 0 1 1 1 1 0>/8"),

  // 5. o chocalho: SHAKER - S2 (rms 0,014, o mais fraco do banco), no contratempo
  s("vhulto_sampling_the_world_drumkit_hats_n_shakers").n(13)
    .struct("~ x ~ x")
    .gain(perlin.range(0.14, 0.26)).hpf(4000)
    .room(0.35).size(4).pan(0.62)
    .mask("<0 0 0 0 1 1 0 0>/8"),

  // 6. a melodia: quatro compassos, uma frase. Triângulo quase puro, porque
  //    qualquer harmônico a mais aqui vira apito no esticador depois.
  note("<[~ g#4 b4 c#5] [e5 ~ c#5 b4] [a4 ~ c#5 e5] [d#5 c#5 b4 ~]>").s("triangle")
    .struct("x*4")
    .attack(0.05).release(0.7).sustain(0.4)
    .gain(0.2).lpf(3200)
    .room(0.72).size(7).delay(0.35).delaytime(0.375).delayfeedback(0.42)
    .pan(0.38)
    .mask("<0 0 0 0 1 1 1 0>/8"),

  // 7. a gêmea: idêntica, 12 cents acima e do outro lado. O batimento entre as
  //    duas é o "analógico" da faixa — não tem reverb envolvido.
  note("<[~ g#4 b4 c#5] [e5 ~ c#5 b4] [a4 ~ c#5 e5] [d#5 c#5 b4 ~]>").s("triangle")
    .struct("x*4")
    .attack(0.08).release(0.9).sustain(0.4)
    .detune(0.12).gain(0.13).lpf(2600)
    .room(0.8).size(8).delay(0.3).delaytime(0.5).delayfeedback(0.35)
    .pan(0.66)
    .mask("<0 0 0 0 0 1 1 0>/8"),

  // 8. a fita: ROLANJ DUPITER, 70 s de chiado com zumbido. É o ruído de fundo
  //    que faz as outras sete parecerem gravadas no mesmo lugar.
  s("vhulto_sampling_the_world_drumkit_texture").n(1)
    .struct("x").slow(19)
    .gain(0.09).hpf(600).lpf(5000).room(0.5)
)

